import { describe, it, expect, beforeEach, vi } from 'vitest';
import { readStoredTheme, writeStoredTheme, THEME_STORAGE_KEY, DEFAULT_THEME } from './theme';

function makeStorage(initial: Record<string, string> = {}) {
  const data: Record<string, string> = { ...initial };
  return {
    data,
    getItem: (k: string) => (k in data ? data[k] : null),
    setItem: (k: string, v: string) => { data[k] = String(v); },
  };
}

describe('theme storage', () => {
  let storage: ReturnType<typeof makeStorage>;
  beforeEach(() => {
    storage = makeStorage();
    vi.stubGlobal('window', { localStorage: storage });
  });

  it('defaults to light when nothing stored', () => {
    expect(DEFAULT_THEME).toBe('light');
    expect(readStoredTheme()).toBe('light');
  });

  it('restores every valid stored theme', () => {
    for (const t of ['light', 'dark', 'light-hc', 'dark-hc', 'system']) {
      storage.data[THEME_STORAGE_KEY] = t;
      expect(readStoredTheme()).toBe(t);
    }
  });

  it('ignores invalid stored values', () => {
    storage.data[THEME_STORAGE_KEY] = 'neon';
    expect(readStoredTheme()).toBe('light');
    storage.data[THEME_STORAGE_KEY] = '';
    expect(readStoredTheme()).toBe('light');
  });

  it('round-trips through write then read', () => {
    writeStoredTheme('dark-hc');
    expect(storage.data[THEME_STORAGE_KEY]).toBe('dark-hc');
    expect(readStoredTheme()).toBe('dark-hc');
  });

  it('does not throw when localStorage is unavailable', () => {
    vi.stubGlobal('window', {
      get localStorage() { throw new Error('SecurityError'); },
    });
    expect(readStoredTheme()).toBe('light');
    expect(() => writeStoredTheme('dark')).not.toThrow();
  });
});
EOF
